tor_v2_001/generator_v3_successor_001\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\nsys.path.insert(0, str(G3))\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\nimport g3_author_contract as contract  # noqa: E402\\\\\\\\\\\\\\\\nimport g3_expression  # noqa: E402\\\\\\\\\\\\\\\\nimport g3_gates  # noqa: E402\\\\\\\\\\\\\\\\nimport g3_lexicon  # noqa: E402\\\\\\\\\\\\\\\\nimport g3_request_builder as rb  # noqa: E402\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\nPKG1 = Path(__file__).resolve().parent\\\\\\\\\\\\\\\\nGATE1 = ROOT / \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"controlled_content_generator_v2_001/gate1_v1_1_001\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\nP5 = GATE1 / \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"p5_p6_300_baseline_scale_and_freeze_001\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\nimport os  # noqa: E402\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\nROUND = int(os.environ.get(\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"PKG1_ROUND\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\", \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"1\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"))\\\\\\\\\\\\\\\\nBATCH_ID = f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"PKG1R{ROUND}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n_RD = PKG1 if ROUND == 1 else PKG1 / f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"round{ROUND}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n# round1/2 共用 v1 场景基座；round≥3 场景经边界措辞再策展（语义不变、风格发牌）成 v2。\\\\\\\\\\\\\\\\n# 执行包5 重跑（round5）复用 v2 边界基座——证据：CP16 用同一 v2 场景即六条全过，\\\\\\\\\\\\\\\\n# 收敛根因在生成器把界限发牌进末段（v3.1 已删 LIMIT_AS_FACT/LATE_FACT）+ 作者未被\\\\\\\\\\\\\\\\n# 要求溶景（v2.3 已加三H/三I），非场景本身，故不再全量再策展场景。请求/输出/审查/\\\\\\\\\\\\\\\\n# 结果始终落 round 子目录。\\\\\\\\\\\\\\\\nSCENARIOS = (_RD / \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"inputs/scenarios.g3.v2.jsonl\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\" if ROUND >= 3\\\\\\\\\\\\\\\\n             else PKG1 / \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"inputs/scenarios.g3.v1.jsonl\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\nREQUESTS = _RD / \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"inputs/requests.g3.v1.jsonl\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\nINPUT_FREEZE 