\\\\\\\\\\\\\\\\\\\\\\"g3_fingerprint.py\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\", \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"g3_similarity.py\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\", \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"g3_request_builder.py\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\",\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"g3_gates.py\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\", \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"g3_route_driver.py\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\", \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"g3_calibration.py\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\",\\\\\\\\\\\\\\\\n]\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\nMIDBATCH_320 = ROOT / (\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"07_microbatch_runs/scoped_content_microbatch_120_001\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n                       \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"/midbatch_320_001/midbatch_320_generation_records.v0.1.jsonl\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\nREF29 = P5 / \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"production/reference_approved.v1.0.jsonl\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\ndef sha256_file(path: Path) -> str:\\\\\\\\\\\\\\\\n    h = hashlib.sha256()\\\\\\\\\\\\\\\\n    with open(path, \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"rb\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\") as f:\\\\\\\\\\\\\\\\n        for chunk in iter(lambda: f.read(1 << 20), b\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"):\\\\\\\\\\\\\\\\n            h.update(chunk)\\\\\\\\\\\\\\\\n    return h.hexdigest()\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\ndef read_jsonl(path: Path) -> list[dict[str, Any]]:\\\\\\\\\\\\\\\\n    return [json.loads(line) for line in path.read_text(encoding=\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"utf-8\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\").splitlines()\\\\\\\\\\\\\\\\n            if line.strip()]\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\ndef write_jsonl(path: Path, rows: list[dict[str, Any]]) -> None:\\\\\\\\\\\\\\\\n    path.parent.mkdir(parents=True, exist_ok=True)\\\\\\\\\\\\\\\\n    with open(path, \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"w\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\", encoding=\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"utf-8\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\") as f:\\\\\\\\\\\\\\\\n        for row in rows:\\\\\\\\\\\\\\\\n            f.write(contract.canonical_json(row) + \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\ndef frozen_corpus() -> dict[str, str]:\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"近原文复现冻结语料：320 中批 body（120 参考的超集，从严）+ 29 既有批准。\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n    corpus: dict[str, str] = {}\\\\\\\\\\\\\\\\n    for row in read_jsonl(MIDBATCH_320):\\\\\\\\\\\\\\\\n        corpus[f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"MB320-{row['output_id']}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"] = str(row[\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"body\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"])\\\\\\\\\\\\\\\\n    for row in read_jsonl(REF29):\\\\\\\\\\\\\\\\n        corpus[f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"REF29-{row['baseline_item_id']}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"] = str(row[\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"body_text\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"])\\\\\\\\\\\\\\\\n    return corpus\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\ndef authors_by_profile() -> dict[str, Any]:\\\\\\\\\\\\\\\\n    def author(cp: str, suffix: str) -> dict[str, str]:\\\\\\\\\\\\\\\\n        sid = f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"G3-AUTHOR-SESSION-{BATCH_ID}-{cp}{suffix}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n        return {\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"author_identity\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\": f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"G3-AUTHOR-{BATCH_ID}-{cp}{suffix}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\",\\\\\\\\\\\\\\\\n                \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"author_session_logical_id\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\": sid,\\\\\\\\\\\\\\\\n                \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"author_platform_agent_id\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\": sid}\\\\\\\\\\\\\\\\n    if ROUND == 1:\\\\\\\\\\\\\\\\n        return {f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"CP{n:02d}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\": author(f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"CP{n:02d}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\", \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\") for n in range(1, 21)}\\\\\\\\\\\\\\\\n    # 第2轮起：每产品两名作者（前3条A、后3条B），打破单脑收敛\\\\\\\\\\\\\\\\n    return {f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"CP{n:02d}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\": [author(f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"CP{n:02d}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\", \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"-A\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"), author(f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"CP{n:02d}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\", \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"-B\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")]\\\\\\\\\\\\\\\\n            for n in range(1, 21)}\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\ndef cmd_freeze_inputs() -> int:\\\\\\\\\\\\\\\\n    contract.require(not INPUT_FREEZE.exists(), \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"E_PKG1_ALREADY_FROZEN\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n    scenarios = read_jsonl(SCENARIOS)\\\\\\\\\\\\\\\\n    contract.require(len(scenarios) == 120, \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"E_PKG1_SCENARIO_COUNT\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\",\\\\\\\\\\\\\\\\n                         f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"{neutral_id}:{sorted(set(leaks))}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n        packet.append(item)\\\\\\\\\\\\\\\\n        mapping.append({\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"neutral_id\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\": neutral_id,\\\\\\\\\\\\\\\\n                        \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"request_id\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\": output[\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"request_id\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"],\\\\\\\\\\\\\\\\n                        \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"profile_id\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\": output[\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"profile_id\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"]})\\\\\\\\\\\\\\\\n    write_jsonl(BLIND_PACKET, packet)\\\\\\\\\\\\\\\\n    write_jsonl(BLIND_MAPPING, mapping)\\\\\\\\\\\\\\\\n    print(f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"blind packet {len(packet)} items, zero label leaks\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n    return 0\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\ndef cmd_metrics() -> int:\\\\\\\\\\\\\\\\n    outputs = {o[\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"request_id\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"]: o for o in read_jsonl(FIRST_OUTPUTS)}\\\\\\\\\\\\\\\\n    gate = json.loads(GATE_REPORT.read_text(encoding=\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"utf-8\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"))\\\\\\\\\\\\\\\\n    gate_by_id = {row[\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"request_id\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"]: row for row in gate[\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"per_output\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"]}\\\\\\\\\\\\\\\\n    content: dict[str, dict[str, Any]] = {}\\\\\\\\\\\\\\\\n    for path in sorted((REVIEW_DIR).glob(\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"content_review.*.jsonl\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")):\\\\\\\\\\\\\\\\n        for row in read_jsonl(path):\\\\\\\\\\\\\\\\n            content[str(row[\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"request_id\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"])] = row\\\\\\\\\\\\\\\\n    fact: dict[str, dict[str, Any]] = {}\\\\\\\\\\\\\\\\n    for path in sorted((REVIEW_DIR).glob(\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"fact_review.*.jsonl\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")):\\\\\\\\\\\\\\\\n        for row in read_jsonl(path):\\\\\\\\\\\\\\\\n            fact[str(row[\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"request_id\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"])] = row\\\\\\\\\\\\\\\\n    blind_choices = {row[\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"neutral_id\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"]: row\\\\\\\\\\\\\\\\n                     for row in read_jsonl(REVIEW_DIR / \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"blind_choices.v1.jsonl\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")}\\\\\\\\\\\\\\\\n    mapping = read_jsonl(BLIND_MAPPING)\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n    total = len(outputs)\\\\\\\\\\\\\\\\n    assert set(content) == set(outputs), \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"content review must cover 100%\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n    assert set(fact) == set(outputs), \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"fact review must cover 100%\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n    def acceptable(rid: str) -> bool:\\\\\\\\\\\\\\\\n        c = content[rid]\\\\\\\\\\\\\\\\n        f = fact[rid]\\\\\\\\\\\\\\\\n        machine_ok = not gate_by_id[rid][\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"machine_first_fail\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"]\\\\\\\\\\\\\\\\n        return (machine_ok and c[\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"grade\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"] in (\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"A\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\", \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"B\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n                and not c[\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"hard_error_codes\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"] and not f[\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"hard_error_codes\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"]\\\\\\\\\\\\\\\\n                and f[\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"fact_approved\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"])\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n    acceptable_ids = sorted(rid for rid in outputs if acceptable(rid))\\\\\\\\\\\\\\\\n    formulaic_ids = sorted(\\\\\\\\\\\\\\\\n        rid for rid in outputs if content[rid][\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"formulaic_or_near_duplicate\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"])\\\\\\\\\\\\\\\\n    hard_veto_ids = sorted(\\\\\\\\\\\\\\\\n        rid for rid in outputs\\\\\\\\\\\\\\\\n        if content[rid][\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"hard_error_codes\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"] or fact[rid][\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"hard_error_codes\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"]\\\\\\\\\\\\\\\\n        or gate_by_id[rid][\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"machine_first_fail\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"])\\\\\\\\\\\